from itertools import combinations

# 群元素
elements = ['e', 'a', 'h', 'b', 'g', 'z', 'ep', 'd']  # e,alpha,eta,beta,gamma,zeta,epsilon,delta
name = {'e':'e','a':'α','h':'η','b':'β','g':'γ','z':'ζ','ep':'ε','d':'δ'}

# 乘法表 (row * col)
# 列顺序: e, α, η, β, γ, ζ, ε, δ
table = {
    'e':  {'e':'e','a':'a','h':'h','b':'b','g':'g','z':'z','ep':'ep','d':'d'},
    'a':  {'e':'a','a':'h','h':'b','b':'e','g':'z','z':'ep','ep':'d','d':'g'},
    'h':  {'e':'h','a':'b','h':'e','b':'a','g':'ep','z':'d','ep':'g','d':'z'},
    'b':  {'e':'b','a':'e','h':'a','b':'h','g':'d','z':'g','ep':'z','d':'ep'},
    'g':  {'e':'g','a':'z','h':'ep','b':'d','g':'e','z':'a','ep':'h','d':'b'},
    'z':  {'e':'z','a':'ep','h':'d','b':'g','g':'a','z':'h','ep':'b','d':'e'},
    'ep': {'e':'ep','a':'d','h':'g','b':'z','g':'h','z':'b','ep':'e','d':'a'},
    'd':  {'e':'d','a':'g','h':'z','b':'ep','g':'b','z':'e','ep':'a','d':'h'},
}

def mul(x, y):
    return table[x][y]

# 验证结合律
from itertools import product
assoc_ok = True
for x,y,z in product(elements, repeat=3):
    if mul(mul(x,y),z) != mul(x,mul(y,z)):
        assoc_ok = False
        print(f"结合律失败: {name[x]}*{name[y]}*{name[z]}")
        break
print(f"结合律: {'通过' if assoc_ok else '失败'}")

# 计算每个元素的阶
def order(x):
    cur = x
    for i in range(1, 20):
        if cur == 'e':
            return i
        cur = mul(cur, x)
    return None

print("\n元素阶:")
for x in elements:
    print(f"  {name[x]}: 阶 {order(x)}")

# 生成循环子群
def cyclic_subgroup(x):
    sub = set()
    cur = 'e'
    for _ in range(20):
        sub.add(cur)
        if cur == 'e' and len(sub) > 1:
            break
        cur = mul(cur, x)
    sub.add('e')
    return sub

print("\n循环子群:")
for x in elements:
    if x != 'e':
        sub = cyclic_subgroup(x)
        print(f"  <{name[x]}> = {{{', '.join(name[e] for e in sorted(sub, key=elements.index))}}}")

# 暴力枚举所有子群
def is_subgroup(S):
    S = set(S)
    if 'e' not in S:
        return False
    for x in S:
        for y in S:
            if mul(x, y) not in S:
                return False
    # 逆元
    for x in S:
        found = False
        for y in S:
            if mul(x, y) == 'e':
                found = True
                break
        if not found:
            return False
    return True

subgroups = []
for size in range(1, 9):
    for combo in combinations(elements, size):
        S = set(combo) | {'e'}
        if len(S) == size and is_subgroup(S):
            subgroups.append(frozenset(S))

print(f"\n所有子群 (共 {len(subgroups)} 个):")
for sg in sorted(subgroups, key=lambda s: (len(s), sorted(s, key=elements.index))):
    members = sorted(sg, key=elements.index)
    print(f"  阶{len(sg)}: {{{', '.join(name[e] for e in members)}}}")
