from itertools import combinations

# 元素列表（按表中的顺序）
elems = ['e','α','η','β','γ','ζ','ε','δ']
n = len(elems)
idx = {e:i for i,e in enumerate(elems)}

# 乘法表（行 × 列）
table = [
    ['e','α','η','β','γ','ζ','ε','δ'],  # e
    ['α','η','β','e','ζ','ε','δ','γ'],  # α
    ['η','β','e','α','ε','δ','γ','ζ'],  # η
    ['β','e','α','η','δ','γ','ζ','ε'],  # β
    ['γ','ζ','ε','δ','e','α','η','β'],  # γ
    ['ζ','ε','δ','γ','α','η','β','e'],  # ζ
    ['ε','δ','γ','ζ','η','β','e','α'],  # ε
    ['δ','γ','ζ','ε','β','e','α','η'],  # δ
]

def mul(a, b):
    return table[idx[a]][idx[b]]

# 验证单位元
assert all(mul('e',x)==x and mul(x,'e')==x for x in elems)

# 计算每个元素的阶
def order(a):
    cur = a
    for k in range(1, n+1):
        if cur == 'e':
            return k
        cur = mul(cur, a)
    return None

print("元素阶：")
for x in elems:
    print(f"  {x}: order {order(x)}")

# 生成循环子群
def cyclic_subgroup(a):
    sub = set()
    cur = a
    while cur != 'e' or not sub:
        sub.add(cur)
        cur = mul(cur, a)
    sub.add('e')
    return frozenset(sub)

print("\n循环子群：")
for x in elems:
    print(f"  <{x}> = {set(cyclic_subgroup(x))}")

# 检查子群：枚举所有子集，验证是否为子群
def is_subgroup(S):
    S = set(S)
    if 'e' not in S:
        return False
    for a in S:
        for b in S:
            if mul(a,b) not in S:
                return False
            # 逆元：找 a^-1 使得 a*a^-1 = e
    # 检查逆元
    for a in S:
        found = False
        for b in S:
            if mul(a,b) == 'e':
                found = True
                break
        if not found:
            return False
    return True

print("\n所有子群：")
subgroups = []
for k in range(1, n+1):
    for combo in combinations(elems, k):
        if 'e' not in combo:
            continue
        if is_subgroup(combo):
            subgroups.append(frozenset(combo))

for sg in subgroups:
    print(f"  阶 {len(sg)}: {set(sg)}")

print(f"\n共 {len(subgroups)} 个子群")
